$featureDescription = @"
Phase: II – Basic Level (Core Essentials) Functional Requirements: Frontend: - Display a list of all tasks - Each task shows: - Title - Completion status (checkbox or indicator) - Add Task: - Input field for task title - Submit button - Update Task: - Ability to edit task title - Delete Task: - Delete button per task - UI updates immediately after any CRUD operation - Clean layout with clear spacing and readable typography Backend: - REST API using FastAPI - Endpoints: - GET /tasks → return all tasks - POST /tasks → create a new task - PUT /tasks/{id} → update task title or status - DELETE /tasks/{id} → delete a task - Input validation: - Title must be non-empty - Proper HTTP status codes - JSON request/response format Database: - PostgreSQL (Neon) - SQLModel ORM - Single table: tasks - Fields: - id (primary key) - title (string, required) - completed (boolean, default false) - created_at (timestamp) - updated_at (timestamp) Non-Functional Requirements: - Stateless backend - Clear API contract - Environment variable for DATABASE_URL - No breaking changes beyond this scope
"@

.specify/scripts/powershell/create-new-feature.ps1 -Json -Number 1 -ShortName "todo-app-mvp" $featureDescription
